BEGIN;
CREATE TEMP TABLE ubaid_test_result(name text,passed boolean) ON COMMIT DROP;
DO $test$
DECLARE tok text:=encode(extensions.gen_random_bytes(24),'hex');uid bigint;r jsonb;plan jsonb;args jsonb;kid bigint;jid bigint;hid bigint;sid bigint;d text;nm text;before_ int;failed_ boolean;day_ date:=(now() at time zone 'Asia/Jakarta')::date;payload_ jsonb;
BEGIN
 SELECT id INTO uid FROM public.users WHERE lower(username)='setyo' LIMIT 1;
 IF uid IS NULL THEN RAISE EXCEPTION 'Test owner unavailable';END IF;
 INSERT INTO private.dk_attendance_session(token,legacy_user_id,username,role,expires_at) VALUES(tok,uid,'Setyo','pemilik',now()+interval '10 minutes');
 SELECT count(*) INTO before_ FROM private.dk_attendance_session;
 r:=public.ubaid_calendar(tok,'snapshot','{}');
 IF r->>'ok'<>'true' OR jsonb_array_length(r->'people')<1 THEN RAISE EXCEPTION 'Snapshot failed: %',r;END IF;
 INSERT INTO ubaid_test_result VALUES('snapshot and shared people',true);
 SELECT did,nama INTO d,nm FROM public.jamaah_desa WHERE status_sambung='Tetap' AND kelompok_nama='PW1' LIMIT 1;
 payload_:=jsonb_build_object('acara_nama','UBAID QA rollback '||tok,'tanggal',day_,'scope_level','desa','status','aktif','waktu','19:00','mode',jsonb_build_array('manual','terminal'),'filter_peserta','{}'::jsonb);
 r:=public.ubaid_calendar(tok,'save',jsonb_build_object('kind','once','payload',payload_,'slots',jsonb_build_array(jsonb_build_object('nama_slot','Pendamping QA','kuota',2)),'targets',jsonb_build_array(d)));
 IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Save failed: %',r;END IF;kid:=(r#>>'{data,id}')::bigint;
 INSERT INTO ubaid_test_result VALUES('create event targets slots atomically',true);
 args:=jsonb_build_object('event_id',kid,'participants',jsonb_build_array(jsonb_build_object('did',d,'nama',nm)));
 plan:=public.ubaid_calendar(tok,'participants',args);IF plan->>'ok'<>'true' THEN RAISE EXCEPTION 'Preview failed: %',plan;END IF;
 r:=public.ubaid_calendar(tok,'participants',args||jsonb_build_object('apply',true,'fingerprint','stale'));
 IF r->>'ok'='true' THEN RAISE EXCEPTION 'Stale preview accepted';END IF;
 r:=public.ubaid_calendar(tok,'participants',args||jsonb_build_object('apply',true,'fingerprint',plan->>'fingerprint'));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Apply failed: %',r;END IF;
 INSERT INTO ubaid_test_result VALUES('preview apply with stale fingerprint protection',true);
 SELECT id INTO hid FROM public.ubnb_kegiatan_hadir WHERE kegiatan_id=kid AND jamaah_did=d;
 r:=public.ubaid_calendar(tok,'attendance',jsonb_build_object('attendance_id',hid,'status','hadir'));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Attendance failed: %',r;END IF;
 plan:=public.ubaid_calendar(tok,'participants',jsonb_build_object('event_id',kid,'participants','[]'::jsonb));
 IF jsonb_array_length(plan->'protected')<>1 THEN RAISE EXCEPTION 'Attendance not protected: %',plan;END IF;
 INSERT INTO ubaid_test_result VALUES('recorded attendance protected on participant refresh',true);
 SELECT id INTO sid FROM private.ubnb_acara_slot WHERE kegiatan_id=kid LIMIT 1;
 r:=public.ubaid_calendar(tok,'slot_count',jsonb_build_object('event_id',kid,'slot_id',sid,'count',3));IF r->>'ok'='true' THEN RAISE EXCEPTION 'Quota exceeded';END IF;
 r:=public.ubaid_calendar(tok,'slot_count',jsonb_build_object('event_id',kid,'slot_id',sid,'count',1));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Slot count failed: %',r;END IF;
 failed_:=false;BEGIN r:=public.ubaid_calendar(tok,'save',jsonb_build_object('kind','once','event_id',kid,'payload',payload_,'slots','[]'::jsonb));EXCEPTION WHEN OTHERS THEN failed_:=true;END;
 IF NOT failed_ THEN RAISE EXCEPTION 'Recorded slot erased';END IF;
 INSERT INTO ubaid_test_result VALUES('slot quotas and recorded slot preservation',true);
 r:=public.ubaid_calendar(tok,'report',jsonb_build_object('event_id',kid));IF r->>'ok'<>'true' OR (r#>>'{rekap,hadir}')::int<1 THEN RAISE EXCEPTION 'Report failed: %',r;END IF;
 r:=public.ubaid_calendar(tok,'close',jsonb_build_object('event_id',kid));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Close failed: %',r;END IF;
 failed_:=false;BEGIN r:=public.ubaid_calendar(tok,'attendance',jsonb_build_object('attendance_id',hid,'status','sakit'));EXCEPTION WHEN OTHERS THEN failed_:=true;END;IF NOT failed_ THEN RAISE EXCEPTION 'Closed attendance write allowed';END IF;
 failed_:=false;BEGIN r:=public.ubaid_calendar(tok,'slot_count',jsonb_build_object('event_id',kid,'slot_id',sid,'count',0));EXCEPTION WHEN OTHERS THEN failed_:=true;END;IF NOT failed_ THEN RAISE EXCEPTION 'Closed slot write allowed';END IF;
 r:=public.ubaid_calendar(tok,'report',jsonb_build_object('event_id',kid));IF r->>'final'<>'true' THEN RAISE EXCEPTION 'Final report flag missing: %',r;END IF;
 r:=public.ubaid_calendar(tok,'reopen',jsonb_build_object('event_id',kid));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Reopen failed: %',r;END IF;
 INSERT INTO ubaid_test_result VALUES('report finalization write lock reopen',true);
 args:=jsonb_build_object('event_key','K'||kid,'kind','minutes');
 r:=public.ubaid_calendar(tok,'document',args);IF r->>'version'<>'0' THEN RAISE EXCEPTION 'New document wrong version';END IF;
 r:=public.ubaid_calendar(tok,'document',args||jsonb_build_object('action','save','version',0,'payload',jsonb_build_object('discussion','Pengujian rollback','status','final','actions',jsonb_build_array(jsonb_build_object('task','Periksa','person','QA','due',day_::text)),'attachments',jsonb_build_array(jsonb_build_object('name','qa.pdf','mime','application/pdf','base64',encode(convert_to('%PDF-1.4 QA rollback','UTF8'),'base64'))))));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Doc save failed: %',r;END IF;
 r:=public.ubaid_calendar(tok,'document',args);sid:=(r->>'version')::bigint;
 r:=public.ubaid_calendar(tok,'document',args||jsonb_build_object('action','file','payload',jsonb_build_object('id',r#>>'{payload,attachments,0,id}')));IF r->>'ok'<>'true' OR r->>'mime'<>'application/pdf' THEN RAISE EXCEPTION 'Attachment failed: %',r;END IF;
 r:=public.ubaid_calendar(tok,'document',args||jsonb_build_object('action','save','version',0,'payload','{"status":"draft"}'::jsonb));IF r->>'ok'='true' THEN RAISE EXCEPTION 'Stale document accepted';END IF;
 r:=public.ubaid_calendar(tok,'document',args||jsonb_build_object('action','save','version',sid,'payload','{"status":"final","discussion":"Koreksi"}'::jsonb));IF r->>'ok'='true' THEN RAISE EXCEPTION 'Final correction missing reason accepted';END IF;
 INSERT INTO ubaid_test_result VALUES('document versions final correction and attachment download',true);
 payload_:=payload_||jsonb_build_object('acara_nama','UBAID QA routine rollback '||tok,'tanggal_mulai',day_,'waktu_mulai','18:00','recurrence_rule',jsonb_build_object('freq','daily','interval',1));
 r:=public.ubaid_calendar(tok,'save',jsonb_build_object('kind','routine','payload',payload_));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Routine failed: %',r;END IF;jid:=(r#>>'{data,id}')::bigint;
 r:=public.ubaid_calendar(tok,'exception',jsonb_build_object('schedule_id',jid,'date',day_,'payload',jsonb_build_object('aksi','pindah','tanggal_baru',day_+1,'waktu','20:00')));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Exception failed: %',r;END IF;
 r:=public.ubaid_calendar(tok,'restore_exception',jsonb_build_object('schedule_id',jid,'date',day_));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Restore failed: %',r;END IF;
 args:=jsonb_build_object('schedule_id',jid,'date',day_,'participants',jsonb_build_array(jsonb_build_object('did',d,'nama',nm)));
 plan:=public.ubaid_calendar(tok,'participants',args);r:=public.ubaid_calendar(tok,'participants',args||jsonb_build_object('apply',true,'fingerprint',plan->>'fingerprint'));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Routine generate failed: %',r;END IF;
 r:=public.ubaid_calendar(tok,'participants',args||jsonb_build_object('date',day_+10));IF r->>'ok'='true' THEN RAISE EXCEPTION 'H7 restriction missing';END IF;
 r:=public.ubaid_calendar(tok,'save',jsonb_build_object('kind','routine','schedule_id',jid,'effective_date',day_+1,'payload',payload_||jsonb_build_object('waktu_mulai','20:30')));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Update future failed: %',r;END IF;
 INSERT INTO ubaid_test_result VALUES('routine edit future preserves past',true);
 r:=public.ubaid_calendar(tok,'template_participants',jsonb_build_object('template_id',(SELECT acara_id FROM public.ubnb_kegiatan WHERE id=kid),'custom',true,'dids',jsonb_build_array(d)));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Template update failed: %',r;END IF;INSERT INTO ubaid_test_result VALUES('template custom participants',true);
 r:=public.ubaid_calendar(tok,'disable_schedule',jsonb_build_object('schedule_id',jid));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'Disable failed: %',r;END IF;
 INSERT INTO ubaid_test_result VALUES('routine move restore generate H7 disable',true);
 IF (SELECT count(*) FROM private.dk_attendance_session)<>before_ THEN RAISE EXCEPTION 'Ephemeral sessions leaked';END IF;
 INSERT INTO ubaid_test_result VALUES('ephemeral sessions always cleaned',true);
END $test$;
SELECT jsonb_agg(to_jsonb(t)) AS tests FROM ubaid_test_result t;
ROLLBACK;
